# -*- coding: utf-8 -*-
from pathlib import Path
import json, html
from PIL import Image, ImageDraw, ImageFont
out=Path('outputs/color-coverage');r=json.loads((out/'analysis.json').read_text())
labels=['Vermelho / coral','Laranja / âmbar','Amarelo / dourado','Lima / chartreuse','Verde folha','Esmeralda / menta','Teal / turquesa','Ciano / céu','Azul / azure','Índigo / violeta','Púrpura / magenta','Rosa / carmim']
lights=['Muito escuro','Escuro','Intermediário','Claro','Muito claro']
# A standalone diagnostic graphic (not an edited reference image).
fontpath='/System/Library/Fonts/Supplemental/Arial.ttf'
font=ImageFont.truetype(fontpath,18);small=ImageFont.truetype(fontpath,14);large=ImageFont.truetype(fontpath,30)
im=Image.new('RGB',(1480,840),'#0e141e');d=ImageDraw.Draw(im)
d.text((34,24),'COLOR ATLAS · COBERTURA APÓS A EXPANSÃO',font=large,fill='#e9f0f7')
d.text((34,70),f"{r['templates']} templates · {r['controlPoints']:,} pontos · referência sRGB em OKLab",font=font,fill='#a8b9cb')
d.text((34,112),'COBERTURA POR MATIZ E LUMINOSIDADE — MENOR % = MAIS LACUNAS',font=font,fill='#e9f0f7')
for h,label in enumerate(labels):
 x=173+h*103
 # rotated labels would be harder to scan; use two rows of short hue-family names.
 first=label.split(' / ')[0];d.text((x+3,150),first,font=small,fill='#bac9d8')
for li,label in enumerate(lights):
 y=181+li*62;d.text((32,y+19),label,font=small,fill='#cbd6e1')
 for hi in range(12):
  cell=next(c for c in r['heatmap'] if c['hue']==hi and c['lightness']==li);v=cell['covered025Pct'];x=173+hi*103
  color='#243141' if v is None else ('#81354d' if v<75 else '#765738' if v<90 else '#265f61' if v<98 else '#255b4e')
  d.rounded_rectangle((x,y,x+96,y+55),radius=5,fill=color);d.text((x+22,y+17),'—' if v is None else f'{v:.0f}%',font=font,fill='white')
d.text((34,522),'AMOSTRAS COM MAIOR DISTÂNCIA RESIDUAL DOS TEMPLATES ATUAIS',font=font,fill='#e9f0f7')
for i,g in enumerate(r['gaps'][:7]):
 x=34+i*201;d.rounded_rectangle((x,565,x+183,624),radius=5,fill=g['hex']);d.text((x,636),g['hex'],font=font,fill='#e6edf5')
 d.rounded_rectangle((x,671,x+80,697),radius=3,fill=g['nearestHex']);d.text((x+88,676),g['nearestHex'],font=small,fill='#acbfd1')
d.text((34,735),'Faixa larga: cor de referência. Faixa pequena: cor mais próxima já produzida por um template.',font=small,fill='#bac9d8')
d.text((34,766),'Cobertura = cor próxima a ΔEOK ≤ 0,025. Critério de auditoria; não é um limite universal de percepção.',font=small,fill='#98abbe')
d.text((34,792),'A análise considera o gamut sRGB do app, não todas as cores visíveis ou condições de visão humana.',font=small,fill='#98abbe')
im.save(out/'coverage-overview.png')
public={**r,'labels':labels,'lightLabels':lights}
styles='''*{box-sizing:border-box}body{background:#0e141e;color:#e6edf5;font:15px/1.55 system-ui;margin:0 auto;padding:35px 24px;max-width:1260px}h1{font-size:34px;margin:0 0 8px}h2{font-size:22px;margin:32px 0 12px}p{color:#b6c5d5;max-width:1000px}a{color:#8dd4ea}button,select{background:#1b293b;color:inherit;border:1px solid #53677d;padding:8px;border-radius:5px}.stats{display:flex;gap:14px;flex-wrap:wrap}.stats div{background:#192333;padding:14px 22px;border-radius:8px}.stats strong{display:block;font-size:26px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}article{background:#192333;padding:16px;border-radius:8px}article h3{font-size:16px;margin:8px 0}.patch{height:66px;border-radius:6px}.pair{display:flex;align-items:center;gap:10px}.near{width:80px;height:26px;border-radius:4px;display:inline-block}.hint{font-size:13px;color:#93a8bd}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px;border-bottom:1px solid #314256;text-align:left}th{color:#b6c5d5;font-weight:500}.table-wrap{overflow:auto}.heatmap th,.heatmap td{text-align:center;min-width:73px}.heatmap td{color:white;border:3px solid #0e141e}.heatmap{min-width:960px}.swatch{display:inline-block;width:16px;height:16px;border-radius:3px;vertical-align:middle;margin-right:7px}.pill{display:inline-block;padding:3px 7px;border-radius:4px;background:#26394a}details{background:#192333;border-radius:8px;padding:16px;margin-top:20px}summary{cursor:pointer}.bars{height:10px;background:#2a3648;width:160px;display:inline-block;margin-right:8px}.bars>i{height:100%;display:block;background:#73bace}.callout{border-left:3px solid #a993e9;padding:8px 18px;background:#192333}footer{margin-top:28px;color:#879ab0}'''
body='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Color Atlas · Cobertura de cores</title><style>'''+styles+'''</style><body>
<h1>Quais cores estão menos contempladas?</h1><p>Análise de toda a biblioteca atual do Color Atlas. O maior déficit é de <strong>chroma alto em púrpuras, violetas, magentas e azuis profundos</strong>, seguido por verdes elétricos claros. A biblioteca cobre bem tons suaves e intermediários.</p>
<div class="stats"><div><strong>887</strong>templates</div><div><strong>5.755</strong>pontos de controle</div><div><strong>4.622</strong>HEX distintos nos pontos</div><div><strong>54.198</strong>cores de referência sRGB</div></div>
<p class="callout">O que falta é intensidade e extensão dessas famílias, não simplesmente mais templates com nomes “purple” ou “blue”. Paletas artísticas não precisam ocupar todo o gamut; esta auditoria serve para orientar novas opções, preservando as atuais.</p>
<h2>As regiões que merecem prioridade</h2>
<div class="table-wrap"><table><thead><tr><th>Prioridade</th><th>Região</th><th>Exemplos</th><th>Aplicações propostas</th></tr></thead><tbody>
<tr><td>1</td><td>Púrpura / magenta intenso, L 60–80%</td><td><span class="swatch" style="background:#F005FE"></span>#F005FE · #C516FC</td><td>Plasma, iridescência, energia arcana, flores intensas</td></tr>
<tr><td>2</td><td>Índigo / violeta intenso, L 40–60%</td><td><span class="swatch" style="background:#8809FE"></span>#8809FE · #5606EC</td><td>Descargas, void, óptica, pigmentos violetas</td></tr>
<tr><td>3</td><td>Azul profundo saturado, L 20–60%</td><td><span class="swatch" style="background:#0306F4"></span>#0306F4 · #0B03C1</td><td>Luz azul, tecnologia, magia, superfícies emissivas</td></tr>
<tr><td>4</td><td>Verde elétrico claro, L 80–100%</td><td><span class="swatch" style="background:#2CF722"></span>#2CF722</td><td>Veneno, bioluminescência, folhas contra luz</td></tr>
<tr><td>5</td><td>Fúcsia / rosa muito saturado, L 60–80%</td><td><span class="swatch" style="background:#FB5BFD"></span>#FB5BFD</td><td>Flores, criaturas coloridas, energia e interface estilizada</td></tr>
</tbody></table></div><p class="hint">Nomes de famílias são aproximações. Exemplos são cores de referência calculadas dentro do gamut, arredondadas para HEX; as distâncias usam os valores sem arredondamento. Os usos são propostas de direção de arte.</p>
<h2>Frequência e lacunas são coisas diferentes</h2><p>A área mede quanto espaço a família ocupa nos gradients, dando o mesmo peso a cada template e respeitando a posição dos pontos. A cobertura mede quantas cores possíveis daquela região ficam próximas de algum gradient. Ter pouca área não significa necessariamente que uma família esteja ausente.</p><label for="threshold">Proximidade usada na auditoria: </label><select id="threshold"><option value="covered025Pct">Mais exigente · ΔEOK ≤ 0,025</option><option value="covered04Pct">Mais ampla · ΔEOK ≤ 0,040</option></select>
<div class="table-wrap"><table><thead><tr><th>Família OKLCH</th><th>Área dos gradients</th><th>Templates que visitam</th><th>Cobertura da região</th><th>Uso relativo*</th></tr></thead><tbody id="hues"></tbody></table></div><p class="hint">*Área cromática dividida pelo volume cromático da região no gamut sRGB, em uma grade uniforme de OKLab. Abaixo de 1: menos presente que essa referência geométrica. Acima de 1: mais frequente. Isso não impõe proporções ideais à arte. Neutros (C &lt; 0,02) ficam fora deste ranking por matiz.</p>
<h2>Cobertura por matiz e luminosidade</h2><p>Quanto menor a porcentagem, mais lacunas. As células incluem todos os chromas acima de 0,02; uma célula com boa média ainda pode ter lacunas na borda saturada do gamut.</p><div class="table-wrap" id="heatmap"></div>
<h2>O déficit de chroma alto</h2><div class="table-wrap"><table><thead><tr><th>Chroma OKLab</th><th>Área dos gradients</th><th>Cobertura</th></tr></thead><tbody id="chroma"></tbody></table></div><p>As cores com C ≥ 0,22 ocupam apenas <strong>0,18% da área média dos gradients</strong>. Com o critério mais exigente, sua cobertura é cerca de <strong>39%</strong>, enquanto chromas moderados e suaves ficam acima de 99%. Chroma alto é uma medida absoluta: o máximo disponível depende de matiz e luminosidade.</p>
<h2>Amostras das lacunas</h2><p>Compare a cor alvo com a cor mais próxima que algum template produz. A busca inclui todos os pontos e transições Smooth, com amostragem adaptativa por segmento.</p><div class="grid" id="gaps"></div>
<details><summary>Método, limites e dados completos</summary><p>887 templates; 257 amostras uniformes por gradient para frequência, com pesos trapezoidais. Para cobertura, mais 652.484 amostras adaptativas de transições, com espaçamento de no máximo 0,001 em OKLab antes do clipping, além dos pontos originais. As amostras passam pela função de interpolação real do app. A referência é uma grade cartesiana em OKLab com passo 0,01, restrita ao gamut sRGB.</p><p>Distância euclidiana em OKLab, coordenadas padrão L 0–1. O app usa a/b escalados por 250 e L por 100; esses fatores foram corrigidos na análise. A busca de vizinhos foi conferida por cálculo exaustivo em 64 posições determinísticas; conversões e contagens também foram verificadas.</p><p>ΔEOK 0,025 e 0,040 são tolerâncias desta auditoria, não limiares universais de distinção humana. OKLab aproxima diferenças perceptuais em visão de cores normal; não substitui ensaios de percepção, as elipses locais de MacAdam ou a avaliação de daltonismo. Não modelamos calibração, tamanho da amostra, HDR, bloom, exposição, transparência ou contexto visual.</p><p>O domínio analisado é sRGB/D65. Isso não é todo o espectro visível: há cores visíveis fora do gamut e cores não espectrais, como magenta, que não correspondem a um único comprimento de onda. Mapas categóricos em Bands precisam de uma auditoria de classes distinta; aqui a comparação usa Smooth, que é o padrão atual do app.</p><p>Referências: <a href="https://bottosson.github.io/posts/oklab/">Definição e implementação de OKLab</a> · <a href="https://registry.color.org/rgb-registry/srgb">Registro sRGB — ICC</a>.</p><p>Dados: <a href="analysis.json">JSON completo</a> · <a href="hue-coverage.csv">Cobertura por matiz</a> · <a href="region-coverage.csv">Regiões por matiz, luz e chroma</a> · <a href="color-gaps.csv">Amostras das lacunas</a> · <a href="coverage-overview.png">Visão geral em imagem</a>.</p></details>
<footer>Análise da biblioteca local em 4 de outubro de 2026. Templates preservados.</footer>
'''
script='''<script>const report=__DATA__;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const key=document.getElementById('threshold').value;document.getElementById('hues').innerHTML=[...report.hues].sort((a,b)=>a.representationRatio-b.representationRatio).map(h=>`<tr><td>${report.labels[h.hue]} <small>${h.degrees.join('–')}°</small></td><td>${h.gradientAreaPct.toFixed(2)}%</td><td>${h.templatesVisiting}</td><td><span class="bars"><i style="width:${h[key]}%"></i></span>${h[key].toFixed(1)}%</td><td>${h.representationRatio.toFixed(2)}×</td></tr>`).join('');document.getElementById('chroma').innerHTML=report.chroma.map((c,i)=>`<tr><td>${['Neutro · C < 0,02','Suave · 0,02–0,06','Moderado · 0,06–0,14','Intenso · 0,14–0,22','Muito intenso · C ≥ 0,22'][i]}</td><td>${c.gradientAreaPct.toFixed(2)}%</td><td>${c[key].toFixed(1)}%</td></tr>`).join('');let table='<table class="heatmap"><thead><tr><th>Luminosidade</th>'+report.labels.map(h=>'<th>'+h.replace(' / ','<br>')+'</th>').join('')+'</tr></thead><tbody>';for(let l=0;l<5;l++){table+='<tr><th>'+report.lightLabels[l]+'</th>';for(let h=0;h<12;h++){const cell=report.heatmap.find(c=>c.hue===h&&c.lightness===l),v=cell[key];table+=`<td title="${cell.gridCells} cores de referência" style="background:${v==null?'#243141':v<75?'#81354d':v<90?'#765738':v<98?'#265f61':'#255b4e'}">${v==null?'—':v.toFixed(0)+'%'}</td>`;}table+='</tr>';}document.getElementById('heatmap').innerHTML=table+'</tbody></table>';}document.getElementById('gaps').innerHTML=report.gaps.map(g=>`<article><div class="patch" style="background:${g.hex}"></div><h3>${g.hex}</h3><p class="hint">L ${(g.lab[0]*100).toFixed(0)}% · C ${g.chroma.toFixed(3)} · h ${g.hue.toFixed(0)}°</p><div class="pair"><span class="near" style="background:${g.nearestHex}"></span><span>${g.nearestHex}</span></div><p class="hint">Mais próxima em ${esc(g.nearestPreset)}.<br>Distância ΔEOK ${g.distance.toFixed(3)}.</p></article>`).join('');document.getElementById('threshold').addEventListener('change',render);render();</script></body></html>'''
# Keep counts and measured statements aligned with the current audit.
for old,value in [('887',r['templates']),('5.755',r['controlPoints']),('4.622',r['uniqueStopHexes']),('54.198',r['referenceCells']),('652.484',r['adaptivePathSamples'])]:
 body=body.replace(str(old),f'{value:,}'.replace(',','.'))
high=r['chroma'][-1]
body=body.replace('<strong>0,18% da área média dos gradients</strong>',f"<strong>{high['gradientAreaPct']:.2f}% da área média dos gradients</strong>".replace('.',','))
body=body.replace('<strong>39%</strong>',f"<strong>{high['covered025Pct']:.1f}%</strong>".replace('.',','))
if Path('outputs/color-coverage-before-expansion/analysis.json').exists():
 before=json.loads(Path('outputs/color-coverage-before-expansion/analysis.json').read_text())
 body=body.replace('O maior déficit é de <strong>chroma alto em púrpuras, violetas, magentas e azuis profundos</strong>, seguido por verdes elétricos claros. A biblioteca cobre bem tons suaves e intermediários.', 'A expansão adicionou <strong>40 templates</strong> para púrpuras, violetas, magentas, azuis profundos, verdes elétricos e fúcsias. A biblioteca atual possui <strong>927 templates</strong>. Ainda há lacunas, especialmente no chroma alto, mas as regiões auditadas melhoraram.')
 body=body.replace('As regiões que merecem prioridade','Regiões que orientaram os novos templates')
 body=body.replace('O que falta é intensidade e extensão dessas famílias, não simplesmente mais templates com nomes “purple” ou “blue”. Paletas artísticas não precisam ocupar todo o gamut; esta auditoria serve para orientar novas opções, preservando as atuais.', 'Os 40 templates ampliam intensidade e extensão dessas famílias. Os 887 templates anteriores foram preservados, inclusive suas posições e proporções. A análise mede cobertura de cor; paletas artísticas não precisam ocupar todo o gamut.')
 b=before['chroma'][-1]
 comparison=f"<h2>Resultado da expansão</h2><table><thead><tr><th>Critério ΔEOK ≤ 0,025</th><th>Antes</th><th>Depois</th></tr></thead><tbody><tr><td>Cobertura geral sRGB</td><td>{before['overall']['covered025Pct']:.1f}%</td><td>{r['overall']['covered025Pct']:.1f}%</td></tr><tr><td>Cobertura de chroma alto</td><td>{b['covered025Pct']:.1f}%</td><td>{high['covered025Pct']:.1f}%</td></tr><tr><td>Área de chroma alto nos gradients</td><td>{b['gradientAreaPct']:.2f}%</td><td>{high['gradientAreaPct']:.2f}%</td></tr></tbody></table><p class='hint'>Mesma referência de 54.198 cores e mesmo critério de proximidade. <a href='../color-coverage-before-expansion/index.html'>Auditoria anterior preservada</a>.</p>"
 body=body.replace('<h2>Frequência e lacunas são coisas diferentes</h2>',comparison+'<h2>Frequência e lacunas são coisas diferentes</h2>')

if 'independentValidation' in r:
 previous=json.loads(Path('outputs/color-coverage-before-fill/analysis.json').read_text())
 additions=r['templates']-previous['templates']
 body=body.replace('Quais cores estão menos contempladas?','Cobertura da biblioteca de cores')
 old_intro='A expansão adicionou <strong>40 templates</strong> para púrpuras, violetas, magentas, azuis profundos, verdes elétricos e fúcsias. A biblioteca atual possui <strong>927 templates</strong>. Ainda há lacunas, especialmente no chroma alto, mas as regiões auditadas melhoraram.'
 new_intro=f"A biblioteca atual possui <strong>{r['templates']} templates</strong>. Foram adicionadas 40 paletas saturadas, 51 estudos de cor por matiz e luminosidade, 24 paletas gráficas Stylized e 20 templates de novas direções estilizadas e 24 paletas de ilustração e materiais e 12 estudos de limiar cromático e 8 paletas de natureza-morta pictórica e 20 variações Tone Shift com luminosidade compartilhada. A cobertura medida alcançou <strong>{r['overall']['covered025Pct']:.2f}%</strong> na referência original e <strong>{r['independentValidation']['covered025Pct']:.3f}%</strong> em uma grade independente."
 body=body.replace(old_intro,new_intro)
 body=body.replace('Os 40 templates ampliam intensidade e extensão dessas famílias. Os 887 templates anteriores foram preservados, inclusive suas posições e proporções. A análise mede cobertura de cor; paletas artísticas não precisam ocupar todo o gamut.',f"Os {previous['templates']} templates anteriores à segunda expansão foram preservados, inclusive suas posições e proporções. Cobertura aqui significa ter uma cor próxima dentro da tolerância definida; não é uma garantia de cobrir todas as cores visíveis ou de preferência artística.")
 body=body.replace('O déficit de chroma alto','Cobertura de chroma alto')
 body=body.replace('Amostras das lacunas','Amostras com maior distância residual')
 body=body.replace('Compare a cor alvo com a cor mais próxima que algum template produz.', 'Todas as amostras abaixo estão dentro da tolerância de cobertura. Compare a cor de referência com a cor mais próxima que algum template produz.')
 body=body.replace('Faixa larga: cor alvo pouco contemplada.', 'Faixa larga: cor de referência.')
 v=r['independentValidation']
 validation=f"<h2>Validação independente</h2><p>Uma segunda grade foi deslocada 0,005 nos eixos L, a e b e novamente limitada ao gamut sRGB. Seus <strong>{v['referenceCells']:,} pontos</strong> não foram usados na escolha dos novos controles. Cobertura no mesmo critério: <strong>{v['covered025Pct']:.3f}%</strong>; maior distância residual: <strong>{v['maxDistance']:.5f}</strong>.</p><p>Na última etapa, a cobertura geral passou de {previous['overall']['covered025Pct']:.2f}% para {r['overall']['covered025Pct']:.2f}%; a de chroma alto passou de {previous['chroma'][-1]['covered025Pct']:.2f}% para {r['chroma'][-1]['covered025Pct']:.2f}%. <a href='../color-coverage-before-fill/index.html'>Auditoria anterior à segunda expansão</a>.</p>"
 body=body.replace('<h2>Frequência e lacunas são coisas diferentes</h2>',validation+'<h2>Frequência e lacunas são coisas diferentes</h2>')

script=script.replace('__DATA__',json.dumps(public,ensure_ascii=False).replace('</','<\\/'))
(out/'index.html').write_text(body+script)
print('PASS: report, interactive threshold comparisons, overview image and downloadable CSV/JSON generated.')
